contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params are caller (ignored since calls come from this contract), owner candidate,
    // recipient to withdraw to, and an amount of ether to fund c before the withdraw attempt.
    function run(address ownerCandidate, address payable recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Deploying test uses already-deployed c; set up its owner via constructor was done by deployer.
        // Fund contract c with fundAmount wei from this contract.
        // Send Ether to c using its fallback (payable) by invoking a plain transfer to address(c).
        // Use low-level call to forward Ether from this contract to c.
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Observe balance before
        uint256 beforeBal = address(c).balance;

        // Try to invoke withdrawAll with this contract as msg.sender (this contract is NOT necessarily owner).
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balance after
        uint256 afterBal = address(c).balance;

        // Determine owner getter value
        address currentOwner = c.owner();

        // General rule: if this contract (msg.sender) equals owner then withdrawAll must succeed and transfer entire balance to recipient
        // Otherwise it must revert and balance must remain unchanged.
        // Note: msg.sender for calls to c is this test contract's address, i.e., address(this)
        assert(
            (currentOwner == address(this) && !reverted && afterBal == 0) ||
            (currentOwner != address(this) && reverted && afterBal == beforeBal)
        );
    }

    // Allow receiving Ether to fund tests
    receive() external payable {}
}

