contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address possibleOwner, address payable recipient, uint256 deposit) public payable {
        require(address(this).balance >= deposit);
        // Deploy constructor already happened externally; c is a fresh C provided by the harness.
        // However, we need to ensure the contract's owner equals possibleOwner for the test to explore both branches.
        // The harness deploys c with some owner; we will read it.
        address owner = c.owner();

        // Fund contract c with `deposit` from this test contract
        if (deposit > 0) {
            // ensure we have balance, already required above
            (bool sent, ) = address(c).call{value: deposit}("");
            require(sent);
        }

        // Record balances before calling withdrawAll
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = address(recipient).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool didRevert;
        try c.withdrawAll(recipient) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = address(recipient).balance;

        // General rule asserted:
        // If the call did not revert, then msg.sender (this contract) must have been owner and all Ether moved from c to recipient (c balance now zero and recipient gained exactly beforeC).
        // If the call reverted, then either msg.sender was not owner OR no funds were transferred (balance unchanged).
        assert(
            (!didRevert && owner == address(this) && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            || (didRevert && (owner != address(this) || (afterC == beforeC && afterRecipient == beforeRecipient)))
        );
    }

    receive() external payable {}
}

