contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with parameters: owner address, callerIsOwner flag, amount sent to contract, and recipient
    function run(address ownerAddr, bool callerIsOwner, uint256 depositAmount, address payable recipient) public payable {
        // ensure this contract has enough balance to forward depositAmount when needed
        require(address(this).balance >= depositAmount);
        // Re-deploy or assume c was constructed with ownerAddr by the checker; we only interact with c.
        // Ensure recipient is not zero to avoid transfer to address(0) which still works but is less meaningful
        require(recipient != address(0));

        // initial observed balances
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // If depositAmount > 0, fund c by sending Ether to its fallback from this contract
        if (depositAmount > 0) {
            // send Ether to c's fallback
            (bool ok, ) = address(c).call{value: depositAmount}("");
            // require that the funding succeeded for the test scenario
            require(ok);
            beforeC += depositAmount;
            beforeThis -= depositAmount;
        }

        // Decide who will call withdrawAll: either the owner or some other address.
        // Since calls to c will have msg.sender == address(this), emulate other caller by calling c through a minimal proxy contract created here.
        // We need to create such a caller inline. Use a small helper contract defined via assembly (minimal proxy) is not allowed; instead create a simple caller contract.
        OtherCaller oc = new OtherCaller(c);

        // set the caller's notion of owner: the actual owner of c is ownerAddr (constructor of C set it). We'll instruct oc whether to call as owner by making oc forward a call from this contract but with owner control is not possible; instead, we simulate owner call by having the checker ensure c was constructed with ownerAddr equal to address(this) when callerIsOwner==true.
        // To adhere to constraints (cannot require anything about c's initial state), we will branch: if callerIsOwner is true, we require that c.owner() == address(this); else we require c.owner() != address(this).
        if (callerIsOwner) {
            require(c.owner() == address(this));
        } else {
            require(c.owner() != address(this));
        }

        // Now perform the withdrawAll call and capture whether it reverted.
        bool reverted;
        // If callerIsOwner, call directly from this contract; else have oc call withdrawAll to act as a non-owner caller.
        if (callerIsOwner) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try oc.doWithdraw(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If call was by owner and did not revert, contract balance must be zero and recipient must have gained the funds.
        // We cannot read recipient's balance if it's arbitrary, but we can assert c's balance is zero and this contract's balance changed only if recipient == address(this).
        // Therefore assert two cases:
        // - owner call and not reverted => address(c).balance == 0
        // - non-owner call => reverted == true and address(c).balance == beforeC
        // Combine into single assert formula
        assert(
            (callerIsOwner && !reverted && afterC == 0)
            || (!callerIsOwner && reverted && afterC == beforeC)
        );
    }

    // Allow contract to receive Ether for funding
    receive() external payable {}
}

// Auxiliary minimal caller contract to call withdrawAll from a different msg.sender
contract OtherCaller {
    C c;
    constructor(C _c) payable { c = _c; }
    function doWithdraw(address _recipient) public {
        c.withdrawAll(_recipient);
    }
}

