    function run(address payable recipient, uint256 depositAmount, bool callAsOwner) public payable {
        require(recipient != address(0));
        // ensure this test contract has enough balance to fund c if desired
        require(address(this).balance >= depositAmount);

        // record before balance of c
        uint256 beforeC = address(c).balance;

        // optionally fund c by sending Ether to its fallback
        if (depositAmount > 0) {
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok);
        }

        // determine whether a call from this contract is expected to be owner: read c.owner()
        address ownerAddr = c.owner();
        // decide call mode: if callAsOwner true, require this contract is the owner; otherwise require it's not
        if (callAsOwner) {
            require(ownerAddr == address(this));
        } else {
            require(ownerAddr != address(this));
        }

        // perform withdrawAll as a top-level call and capture revert via try/catch
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;

        // General invariant: successful call => c.balance == 0; reverted call => c.balance unchanged
        assert((!reverted && afterC == 0) || (reverted && afterC == beforeC + depositAmount));
    }

    receive() external payable {}
}

