    constructor(C _c) { c = _c; }

    // params:
    // recipient - address to receive funds if withdraw succeeds
    // fundAmount - amount to send into c before attempting withdraw
    function run(address recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // read owner before any actions
        address owner = c.owner();

        // fund c by sending Ether to it using a plain call to c's fallback
        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok);

        // record balances before withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // attempt withdrawAll as this contract (msg.sender will be this contract)
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If this contract is the owner: call must not revert, c.balance becomes 0, and recipient's balance increases by beforeC.
        // If not owner: call must revert and balances remain unchanged.
        assert(
            (address(this) == owner && !reverted && afterC == 0 &&
                // If recipient is this contract, this contract's balance increases by beforeC; otherwise unchanged.
                ((recipient == address(this) && afterThis == beforeThis + beforeC) || (recipient != address(this) && afterThis == beforeThis)))
            ||
            (address(this) != owner && reverted && afterC == beforeC && afterThis == beforeThis)
        );
    }

    receive() external payable {}
}

