contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    //  addrCaller - address that we will attempt to have call withdrawAll (simulated by using low-level call from this contract)
    //  recipient - recipient passed to withdrawAll
    //  amount - ether to fund c before withdraw
    function run(address addrCaller, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Deploying test runs with a fresh c already deployed by the harness; we observe its owner
        address initialOwner = c.owner();

        // Fund contract c by sending Ether to it from this contract
        // ensure we have enough balance
        (bool sent,) = address(c).call{value: amount}("");
        // sent may be true even if amount==0

        uint256 balanceBefore = address(c).balance;

        // Now attempt withdrawAll as if called by addrCaller.
        // Since the checker runs this test once in a single transaction and msg.sender for calls is this contract,
        // we cannot change msg.sender. To simulate both cases (owner vs non-owner), we will call withdrawAll from this contract
        // only; but we parameterize by addrCaller and assert the logical implication: if addrCaller equals owner then withdraw should not revert when invoked by owner (i.e., when this contract is owner), else it must revert.
        // To make this meaningful, we first check whether this contract equals the provided addrCaller and whether this contract is the owner.

        // We will perform the actual call from this contract. Record whether it reverts.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;
        address postOwner = c.owner();

        // General rule:
        // If the caller (addrCaller) equals the contract owner at start, then when this contract actually is owner (i.e., initialOwner == address(this)) the withdrawAll call from this contract must not revert and contract balance must have decreased by at most balanceBefore (i.e., either transferred all funds) ;
        // Conversely, if addrCaller is not owner then withdrawAll must revert when attempted by a non-owner (ensured by reverted==true OR no balance change).
        // We express a conservative, provable invariant:
        // - If initialOwner == address(this) then the attempt by this contract must not revert and after the call the contract's balance is <= before (funds may be transferred out).
        // - If initialOwner != address(this) then the attempt must revert and balance must be unchanged.

        assert( (initialOwner == address(this) ? (reverted == false && balanceAfter <= balanceBefore) : (reverted == true && balanceAfter == balanceBefore)) );
    }

    // Allow this test contract to receive Ether so it can fund c
    receive() external payable {}
}

