contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function takes parameters to drive behavior
    function run(address possibleOwner, address recipient, uint256 fundAmount, bool senderIsOwner) public payable {
        require(recipient != address(0));
        // Deploy-time owner is the provided possibleOwner; but per problem statement c is already deployed fresh and passed in.
        // We can only interact with the existing c. Ensure we have funds to send to c if needed.
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
            // send Ether to c by calling its fallback payable
            (bool ok,) = address(c).call{value: fundAmount}("");
            require(ok);
        }

        // Read observable state before the withdraw attempt
        uint256 beforeC = address(c).balance;
        address ownerAddr = c.owner();

        // Decide who will call withdrawAll: either the true owner (this contract must be owner) or not.
        // The checker deploys c fresh; ownerAddr is what matters. If senderIsOwner is true but this contract
        // is not the owner, we cannot change msg.sender for c calls; so simulate by requiring consistency.
        // We enforce that if senderIsOwner is true then ownerAddr must equal address(this), otherwise the
        // call will be from non-owner. This keeps behavior determined by parameters and c's public owner.
        if (senderIsOwner) {
            require(ownerAddr == address(this));
        } else {
            require(ownerAddr != address(this));
        }

        // Attempt withdraw and catch revert
        bool reverted;
        uint256 afterC;
        if (senderIsOwner) {
            // as owner, call should succeed and transfer entire balance to recipient
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            afterC = address(c).balance;
        } else {
            // as non-owner, call should revert; we still attempt and record
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            afterC = address(c).balance;
        }

        // Assert the general rule: if call was from owner then it must not revert and C's balance becomes 0
        // and recipient (externally observable only via address(this).balance) may have increased; if from non-owner
        // it must revert and C balance unchanged.
        assert( (senderIsOwner && !reverted && afterC == 0) || (!senderIsOwner && reverted && afterC == beforeC) );
    }

    // allow receiving Ether when c transfers to this test contract as recipient
    receive() external payable {}
}
